using System.IO;
using UnrealBuildTool;

public class FortniteGame : ModuleRules
{
    public FortniteGame(ReadOnlyTargetRules Target) : base(Target)
    {
        PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;
        PublicDependencyModuleNames.AddRange(new[] { "Core", "CoreUObject", "Engine", "InputCore", "NavigationSystem", "AIModule", "Json", "PlayspaceFramework" });
        // Reflection-derived classes, regenerated by porting/promote_native_classes.sh (not hand-edited).
        PublicIncludePaths.Add(Path.Combine(ModuleDirectory, "Generated"));
    }
}
